export function buildLightItin(tour){
  const out=[];
  const regions = tour.regions;
  const perRegion = Math.ceil(tour.days / regions.length);
  const imgMap = { "Rio":IMG.rioChrist, "Salvador":IMG.ribbons, "Manaus":IMG.amazon, "Cuiabá":IMG.pantanal, "Bonito":IMG.pantanal, "Mateiros":IMG.jalapao, "Foz":IMG.iguazu, "Fernando":IMG.noronha, "São Luís":LENCOIS_IMG.saoLuisHistoric, "Lençóis Maranhenses":LENCOIS_IMG.dunesLagoon, "Jericoacoara":IMG.beach, "Porto Alegre":IMG.surfer, "Vale":IMG.surfer, "Gramado":IMG.surfer, "Chapada":IMG.jalapao, "Trancoso":IMG.beach, "Paraty":IMG.paraty, "Ilha":IMG.noronha, "Anavilhanas":IMG.amazon, "Rio Negro":IMG.amazon, "Puerto":IMG.iguazu, "São Paulo":IMG.saoPaulo, "Palmas":IMG.jalapao, "Jalapão":IMG.jalapao, "North Pantanal":IMG.pantanal };
  const lencoisDayImages = [
    LENCOIS_IMG.saoLuisHistoric,
    LENCOIS_IMG.saoLuisTiles,
    LENCOIS_IMG.hero,
    LENCOIS_IMG.dunesLagoon,
    LENCOIS_IMG.lagoonPanorama,
    LENCOIS_IMG.duneWalk,
    LENCOIS_IMG.whiteDunes,
    LENCOIS_IMG.atinsDunes,
    LENCOIS_IMG.preguiçasRiver,
  ];
  function imgFor(r){ const k = Object.keys(imgMap).find(k=>r.startsWith(k) || r.includes(k)); return imgMap[k] || tour.img; }
  let day=1;
  for (let r=0; r<regions.length; r++){
    const reg = regions[r];
    const daysHere = (r===regions.length-1) ? tour.days - day + 1 : perRegion;
    for (let i=0; i<daysHere && day<=tour.days; i++){
      out.push({
        route: i===0 && r>0 ? `${regions[r-1]} → ${reg}` : reg,
        city: reg, img: tour.slug === "lencois" ? (lencoisDayImages[day - 1] || imgFor(reg)) : imgFor(reg),
        meals: "Desayuno",
        blocks: i===0 ? [
          {kind:"Llegada", title:`Bienvenida a ${reg}`, desc:"Traslado privado y llegada a un alojamiento cuidadosamente seleccionado. Tu guía local te dará una breve introducción; el resto del día será para instalarte con calma."},
          {kind:"Opcional", title:"Paseo al atardecer", desc:"Una breve caminata de orientación con tu guía si tiene energía; de lo contrario, una larga ducha y una cena sin prisas."},
        ] : i===daysHere-1 ? [
          {kind:"Excursión", title:`Un día especial en ${reg}`, desc:"Diseñado en torno a tus intereses: un taller práctico, media jornada en la naturaleza o un día más tranquilo para nadar y leer. Tu guía adaptará el plan al tiempo y a tu ritmo."},
          {kind:"Traslado", title:r<regions.length-1?`Viaje a ${regions[r+1]}`:"Preparativos para la salida", desc: r<regions.length-1 ? "Traslado privado o breve vuelo doméstico hasta la siguiente región.":"Última cena en la ciudad y equipaje listo para el traslado al aeropuerto del día siguiente."},
        ] : [
          {kind:"Excursión", title:`Explorando ${reg}`, desc:`Un día completo entre los lugares imprescindibles y los rincones tranquilos de ${reg}, diseñado por tu experta local y adaptado sobre la marcha.`},
        ]
      });
      day++;
    }
  }
  return out;
}

